import{_ as t,c as r,o as a,ae as i}from"./chunks/framework.BtEkjhVd.js";const m=JSON.parse('{"title":"Architecture Decision Record 1: React JS for Web Development Framework","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr-choose-web-framework/adr1.md","filePath":"architecture/adr-choose-web-framework/adr1.md"}'),o={name:"architecture/adr-choose-web-framework/adr1.md"};function n(s,e,c,d,l,h){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="architecture-decision-record-1-react-js-for-web-development-framework" tabindex="-1">Architecture Decision Record 1: React JS for Web Development Framework <a class="header-anchor" href="#architecture-decision-record-1-react-js-for-web-development-framework" aria-label="Permalink to &quot;Architecture Decision Record 1: React JS for Web Development Framework&quot;">​</a></h1><p>Date: 01/09/2024</p><h1 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h1><p>We are building the fAIr platform that requires high performance, fast development cycles, and scalability. The development team is proficient in React and Next.js, and HOT has a history of using React.js for most of its projects. To maintain consistency and leverage existing knowledge, we are considering web development frameworks that align with our team&#39;s skill set and project requirements.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li>Speed of development: minimizing the time required to build and deploy features.</li><li>Performance: ensuring the web application is highly performant, especially in terms of loading times and SEO.</li><li>Familiarity with the framework: developers are experienced with React and Next.js, reducing the need for additional training.</li><li>Ease of deployment: Avoid vendor lock-in during deployment.</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><p><a href="https://react.dev/" target="_blank" rel="noreferrer">React.js</a>: Familiarity with the team, widely used in the company, rich ecosystem of libraries.</p></li><li><p><a href="https://nextjs.org/" target="_blank" rel="noreferrer">Next.js</a>: Built on top of React, offers server-side rendering and static site generation out of the box, optimized for performance and SEO, familiar to the team.</p></li></ul><h1 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h1><p>We will use React.js as the framework for this project. This decision leverages the team&#39;s extensive knowledge of React.js and its established use within HOT. Additionally, React.js offers straightforward deployment options, which potentially aligns well with HOT&#39;s current DevOps processes. In contrast, while Next.js provides some advanced features, concerns over potential vendor lock-in with Vercel and the complexity of alternative deployment methods make it less suitable for our needs at this time. React.js ensures a smoother and more efficient deployment process without compromising our flexibility.</p><p>The two options (React.js and Next.js) are licensed under very permissive open-source licenses (MIT) meaning they align with HOT license requirements.</p><h1 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h1><p>Proposed.</p><h1 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h1><p>New developers may need a brief period to adapt to React.js if they are only familiar with other frameworks.</p>',15)]))}const f=t(o,[["render",n]]);export{m as __pageData,f as default};
